type Result = { readonly status: "succeeded" | "declined"; readonly amountKobo: number; readonly id: string };

class FakeGateway {
  private readonly byReference = new Map<string, Result>();

  charge(reference: string, amountKobo: number, card: string): Result {
    const previous = this.byReference.get(reference);
    if (previous !== undefined) return previous;
    const result: Result = {
      status: card === "tok_declined" ? "declined" : "succeeded",
      amountKobo,
      id: `ch_${this.byReference.size + 1}`,
    };
    this.byReference.set(reference, result);
    return result;
  }
}

const checks: [string, (g: FakeGateway) => boolean][] = [
  ["amount in kobo", (g) => g.charge("r1", 2_042_500, "tok_visa").amountKobo === 2_042_500],
  ["declines tok_declined", (g) => g.charge("r2", 500, "tok_declined").status === "declined"],
  ["idempotent", (g) => g.charge("r3", 500, "tok_visa").id === g.charge("r3", 500, "tok_visa").id],
];
for (const [name, check] of checks) console.log(check(new FakeGateway()) ? "PASS" : "FAIL", name);

